// 题库按「每轮六个维度各一题」重新排列，任意截取 12 / 24 / 36 题时各维度题数都相同。
const questionBank=(()=>{const byDim=[...baseQuestions,...extraQuestions].reduce((g,q)=>{(g[q.d]=g[q.d]||[]).push(q);return g},[]),rounds=Math.min(...byDim.map(g=>g.length)),out=[];for(let r=0;r<rounds;r++)byDim.forEach(g=>out.push(g[r]));return out})();
let questions=[],index=0,answers=[],lastResult=null,view='home',advanceTimer=null,cycleTimer=null,direction='fwd',lastProgress=0;
const dimensions=[['探索新鲜','偏向熟悉'],['分析问题','关注感受'],['外向交流','安静独处'],['计划有序','灵活应变'],['想象创造','务实落地'],['专注深耕','广泛涉猎']];
const tones=['#dfe8d6','#efe4d2','#e4e1ec','#e3ebe7','#f1e4dc'];
const pad=n=>String(n).padStart(2,'0');
const reduceMotion=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;
function countUp(el){const to=+el.dataset.count,t0=performance.now(),dur=900;if(reduceMotion())return;const step=t=>{const k=Math.min(1,(t-t0)/dur);el.textContent=Math.round(to*(1-(1-k)**3));if(k<1)requestAnimationFrame(step)};el.textContent='0';requestAnimationFrame(step);setTimeout(()=>{el.textContent=to},dur+200)}
// 带 data-reveal 的元素进入视口时淡入上移，里面带 data-count 的数字同时滚动计数。
// 用滚动事件和位置判断而不是 IntersectionObserver，保证后台标签页、截图等场景下内容也一定会出现。
let revealCheck=null;
function reveal(){removeEventListener('scroll',revealCheck);const pending=[...app.querySelectorAll('[data-reveal]')];if(reduceMotion())return pending.forEach(el=>el.classList.add('in'));revealCheck=()=>{for(let i=pending.length-1;i>=0;i--){const el=pending[i],r=el.getBoundingClientRect();if(r.top<innerHeight*.92&&r.bottom>0){el.classList.add('in');el.querySelectorAll('[data-count]').forEach(countUp);pending.splice(i,1)}}if(!pending.length)removeEventListener('scroll',revealCheck)};addEventListener('scroll',revealCheck,{passive:true});setTimeout(revealCheck,30)}
function portrait(p,cls){return `<span class="avatar ${cls}" style="--tone:${tones[p.order%tones.length]}"><b aria-hidden="true">${p.name[0]}</b><img src="portraits/${pad(p.order)}.png" alt="${p.name}的人物插画" loading="lazy" onerror="this.remove()"></span>`}
function show(name,html,toTop=true){view=name;clearTimeout(advanceTimer);clearInterval(cycleTimer);app.innerHTML=`<div class="view">${html}</div>`;reveal();app.querySelectorAll('[data-home]').forEach(b=>b.onclick=home);if(toTop)window.scrollTo({top:0,behavior:'instant'})}
function home(){const preview=people.slice(0,5).map((p,i)=>portrait({...p,order:i},'avatar-sm')).join('');show('home',`<section class="wrap hero"><div class="hero-copy"><div class="eyebrow" data-reveal>A LITTLE JOURNEY INWARD</div><h1 data-reveal style="--d:.08s">发现你的<br><em>另一面。</em></h1><p data-reveal style="--d:.16s">每个人都是一本还没读完的书。<br>从一个有趣的问题开始，探索属于你的独特答案。</p><div class="hero-actions" data-reveal style="--d:.24s"><a class="primary" href="#tests">开始探索 <span>↗</span></a><span class="hero-note"><i class="dot"></i> 给好奇的你，一点灵感</span></div><ul class="hero-stats" data-reveal style="--d:.32s"><li><b data-count="${people.length}">${people.length}</b>位历史人物</li><li><b data-count="${dimensions.length}">${dimensions.length}</b>个性格维度</li><li><b data-count="3">3</b>分钟起</li></ul></div><div class="hero-art" aria-hidden="true" data-reveal style="--d:.15s"><span class="spark s1">✦</span><span class="spark s2">✦</span><span class="spark s3">✧</span><span class="art-index">01 / DISCOVER YOURSELF</span><div class="orbit"><div class="orbit-ring"><i>✦</i><i>✧</i><i>·</i></div><div class="portrait"></div></div><div class="art-tag">A NOTE TO YOURSELF<b>遇见另一个自己 ✳</b></div></div></section><section class="section" id="tests"><div class="wrap"><div class="section-head" data-reveal><div><div class="eyebrow">EXPLORE THE COLLECTION</div><h2>从好奇开始</h2></div><p>选一个你感兴趣的话题，给自己几分钟时间。</p></div><article class="feature" data-reveal style="--d:.1s"><div class="feature-art" aria-hidden="true"><span class="number">PERSONALITY / 01</span><span class="stamp">跨越<br>时空</span><span class="symbol">史</span><div class="avatar-row">${preview}<span class="avatar avatar-sm more">+${people.length-5}</span></div></div><div class="feature-body"><span class="tag">✳ 人格探索 · 现已开放</span><h3>你与哪位历史人物最像？</h3><p>跨越时空，在 ${people.length} 位古今中外的人物里，看看谁和你的思考方式更相近，又与谁最不一样。</p><ul class="feature-meta"><li><b>12 / 24 / 36</b>题量自由选</li><li><b>3–9 分钟</b>即可完成</li><li><b>${dimensions.length} 个维度</b>描绘倾向</li></ul><button class="primary" data-start>开始测试 <span>↗</span></button></div></article><div class="cards" data-reveal style="--d:.15s"><article class="card boundary-card"><img class="boundary-cover" src="assets/boundaries.png" alt="阳光下照料植物的人，代表自在的个人空间" loading="lazy"><div class="card-body"><span class="tag">✳ 人际探索 · 现已开放</span><h3>你的边界感是什么类型？</h3><p>在时间、表达和分享中，找到让自己自在的距离。</p><button class="secondary" data-boundary>开始测试 ↗</button></div></article><article class="card"><div class="card-art art-ancient" aria-hidden="true"><span class="number">02</span><span class="symbol">游</span></div><div class="card-body"><span class="tag">✳ 趣味想象 · 筹备中</span><h3>穿越古代，你会是什么身份？</h3><p>是仗剑远行的游侠，还是运筹帷幄的谋士？</p></div></article><article class="card"><div class="card-art art-gift" aria-hidden="true"><span class="number">03</span><span class="symbol">光</span></div><div class="card-body"><span class="tag">✳ 发现优势 · 筹备中</span><h3>你身上藏着什么天赋？</h3><p>那些习以为常的小习惯，也许正是你的闪光点。</p></div></article></div></div></section><section class="about" id="about"><div class="wrap about-content"><div data-reveal><div class="eyebrow">A NOTE FROM US</div><h2>认识自己，是一段旅程。</h2><p>我们相信，每个答案都可以成为一个新的起点。星笺希望用轻松、有趣的方式，陪你发现自己的不同侧面。</p></div><ul class="principles" data-reveal><li><b>轻松</b><span>几分钟完成，凭第一感觉作答就好。</span></li><li><b>私密</b><span>答案只在你的浏览器里计算，不会上传。</span></li><li><b>坦诚</b><span>仅供趣味探索，不是心理诊断。</span></li></ul></div></section>`);app.querySelector('[data-start]').onclick=chooseLength;app.querySelector('[data-boundary]').onclick=boundaryChoose}
function chooseLength(){const options=[[12,'轻体验','快速探索，初步认识自己的倾向','约 3 分钟'],[24,'标准版','从更多生活场景了解自己','约 6 分钟',true],[36,'深入版','通过更丰富的回答描绘倾向','约 9 分钟']];show('length',`<div class="page"><button class="back" data-home>← 返回测试合集</button><div class="quiz-head"><div class="eyebrow">CHOOSE YOUR JOURNEY</div><h1>选择适合你的探索时间</h1><p>每个版本都会探索六个相同的性格维度。题目越多，覆盖的生活情境越丰富。</p></div><div class="length-list">${options.map(([n,name,desc,time,rec])=>`<button class="length-option${rec?' recommended':''}" data-length="${n}">${rec?'<em>推荐</em>':''}<span class="lo-count">${n}<small>题</small></span><strong>${name}</strong><small>${desc}</small><b>${time} <i>→</i></b></button>`).join('')}</div><p class="disclaimer">结果为趣味探索，更多题目可提供更丰富的参考；本测试尚未经过科学验证，不能保证结果更准确。</p></div>`);app.querySelectorAll('[data-length]').forEach(b=>b.onclick=()=>start(Number(b.dataset.length)))}
function start(length){questions=questionBank.slice(0,length);index=0;direction='fwd';lastProgress=0;answers=Array(questions.length).fill(null);quiz();window.scrollTo({top:0,behavior:'instant'})}
function quiz(){const q=questions[index],last=index===questions.length-1;show('quiz',`<div class="page"><button class="back" data-home>← 返回测试合集</button><div class="quiz-head compact"><div class="eyebrow">A JOURNEY THROUGH TIME</div><h1>你与哪位历史人物最像？</h1></div><div class="progress-meta"><span>穿梭于想象和日常之间，选择最接近你的做法</span><span><b>${pad(index+1)}</b> / ${pad(questions.length)}</span></div><div class="progress" role="progressbar" aria-label="答题进度" aria-valuemin="1" aria-valuemax="${questions.length}" aria-valuenow="${index+1}"><span style="width:${lastProgress}%"></span></div><div class="question ${direction}"><div class="eyebrow">QUESTION ${pad(index+1)}</div><h2>${q.q}</h2><img class="question-illustration" src="question-art/question-${pad(index+1)}.webp" alt="" decoding="async" width="1200" height="675"><div class="options">${q.a.map((a,i)=>`<button class="option${answers[index]===i?' selected':''}" data-option="${i}" style="--i:${i}" aria-pressed="${answers[index]===i}"><span>${'ABCD'[i]}</span>${a}</button>`).join('')}</div></div><div class="quiz-actions"><button class="secondary" id="prev" ${index===0?'disabled':''}>← 上一题</button><span class="key-hint">键盘 1–4 选择 · ← → 切换</span><button class="primary" id="next" ${answers[index]===null?'disabled':''}>${last?'查看结果':'下一题'} <span>→</span></button></div></div>`,false);app.querySelectorAll('[data-option]').forEach(b=>b.onclick=()=>pick(Number(b.dataset.option)));app.querySelector('#prev').onclick=prev;app.querySelector('#next').onclick=next;const bar=app.querySelector('.progress span');lastProgress=(index+1)/questions.length*100;bar.offsetWidth;bar.style.width=lastProgress+'%'}
// 选中后稍作停留自动进入下一题；最后一题需手动点「查看结果」。
function pick(i){answers[index]=i;app.querySelectorAll('[data-option]').forEach((b,j)=>{b.classList.toggle('selected',j===i);b.setAttribute('aria-pressed',j===i)});const chosen=app.querySelectorAll('[data-option]')[i];chosen.classList.remove('pop');chosen.offsetWidth;chosen.classList.add('pop');app.querySelector('#next').disabled=false;clearTimeout(advanceTimer);if(index<questions.length-1)advanceTimer=setTimeout(next,320)}
function prev(){if(index>0){index--;direction='back';quiz();document.querySelector('.question').scrollIntoView({block:'start',behavior:'instant'})}}
function next(){if(answers[index]===null)return;if(index<questions.length-1){index++;direction='fwd';quiz();document.querySelector('.question').scrollIntoView({block:'start',behavior:'instant'})}else analyzing()}
// 出结果前的过场：人物名字快速轮换，营造「跨越时空」寻找的感觉。
function analyzing(){if(reduceMotion())return result();show('loading',`<div class="page loading"><div class="loading-orbit" aria-hidden="true"><i>✦</i><i>✧</i><i>✦</i><span class="loading-core">✳</span></div><p class="loading-text">正在跨越时空，寻找与你相近的人</p><p class="loading-name" id="cycle" aria-hidden="true">${people[0].name}</p></div>`);let k=0;const el=app.querySelector('#cycle');cycleTimer=setInterval(()=>{el.textContent=people[++k%people.length].name},90);advanceTimer=setTimeout(result,1600)}
// 多维雷达图：每个维度一条轴，分值 1–5 由内向外；实线实心点为你，虚线空心点为对比人物。
function radar(user,other){
 const n=dimensions.length,W=440,H=360,cx=220,cy=180,R=110,ang=i=>-Math.PI/2+i*2*Math.PI/n;
 const pt=(v,i,r=R*v/5)=>[cx+Math.cos(ang(i))*r,cy+Math.sin(ang(i))*r],poly=vs=>vs.map((v,i)=>pt(v,i).map(x=>x.toFixed(1)).join(',')).join(' '),fmt=v=>String(Math.round(v*10)/10);
 const label=(d,i)=>{const c=Math.cos(ang(i)),s=Math.sin(ang(i)),[x,y]=pt(0,i,R+24),a=Math.abs(c)<.3?'middle':c>0?'start':'end',ly=y+(s<-.3?-14:s>.3?6:-6);return `<text class="ax" x="${x}" y="${ly}" text-anchor="${a}">${d[0]}<tspan class="ax-sub" x="${x}" dy="17">（${d[1]}）</tspan></text>`};
 const dots=(vs,cls,r)=>vs.map((v,i)=>{const[x,y]=pt(v,i);return `<circle class="dot ${cls}" cx="${x}" cy="${y}" r="${r}"/>`}).join('');
 const hits=dimensions.map((_,i)=>{const k=R*1.2,a=ang(i)-Math.PI/n,b=ang(i)+Math.PI/n,[x,y]=pt(Math.max(user[i],other.v[i]),i);return `<polygon class="hit" tabindex="0" data-axis="${i}" data-x="${x/W*100}" data-y="${y/H*100}" data-tip="你 ${fmt(user[i])} · ${other.name} ${other.v[i]}" points="${cx},${cy} ${cx+Math.cos(a)*k},${cy+Math.sin(a)*k} ${cx+Math.cos(b)*k},${cy+Math.sin(b)*k}"/>`}).join('');
 return `<div class="radar-legend"><span class="lg-you">你</span><span class="lg-other">${other.name}</span></div><div class="radar-box"><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="倾向雷达图：${dimensions.map((d,i)=>`${d[0]}，你 ${fmt(user[i])} 分，${other.name} ${other.v[i]} 分`).join('；')}">${[1,2,3,4,5].map(k=>`<polygon class="ring${k===5?' outer':''}" points="${poly(Array(n).fill(k))}"/>`).join('')}${dimensions.map((_,i)=>{const[x,y]=pt(5,i);return `<line class="axis" x1="${cx}" y1="${cy}" x2="${x}" y2="${y}"/>`}).join('')}${dimensions.map(label).join('')}<polygon class="shape other" points="${poly(other.v)}"/><polygon class="shape you" points="${poly(user)}"/>${dots(other.v,'other',4)}${dots(user,'you',5)}${hits}</svg><div class="radar-tip" hidden></div></div>`;
}
function bindRadar(){const box=app.querySelector('.radar-box'),tip=box.querySelector('.radar-tip');box.querySelectorAll('.hit').forEach(h=>{const on=()=>{tip.innerHTML=`<b>${dimensions[h.dataset.axis][0]}</b>${h.dataset.tip}`;tip.style.left=h.dataset.x+'%';tip.style.top=h.dataset.y+'%';tip.hidden=false},off=()=>{tip.hidden=true};h.onpointerenter=on;h.onfocus=on;h.onpointerleave=off;h.onblur=off})}
function result(){
 const totals=Array(dimensions.length).fill(0); questions.forEach((q,i)=>{totals[q.d]+=(q.v||[5,4,2,1])[answers[i]]});
 const user=totals.map(x=>x/(questions.length/dimensions.length));
 // 相近度：每个维度都差 4 分时距离最大（√(16×维度数)），按欧氏距离折算成百分比。
 const ranked=people.map((p,order)=>({...p,order,distance:p.v.reduce((sum,n,i)=>sum+(n-user[i])**2,0)})).sort((a,b)=>a.distance-b.distance||a.order-b.order).map(p=>({...p,score:Math.round(100*(1-Math.sqrt(p.distance/(16*dimensions.length))))}));
 const near=ranked[0], far=ranked[ranked.length-1];
 const lean=(i,value)=>{const off=value-3,side=off>0?dimensions[i][0]:dimensions[i][1];return Math.abs(off)<.5?'两者兼顾':(Math.abs(off)<1.25?'略偏':'明显偏向')+side};
 const similarities=near.v.map((v,i)=>({i,d:Math.abs(user[i]-v)})).sort((a,b)=>a.d-b.d||a.i-b.i).slice(0,2).map(x=>dimensions[x.i][0]+' / '+dimensions[x.i][1]).join('、');
 const contrasts=far.v.map((v,i)=>({i,d:Math.abs(user[i]-v)})).sort((a,b)=>b.d-a.d||a.i-b.i).slice(0,2).map(x=>dimensions[x.i][0]+' / '+dimensions[x.i][1]).join('、');
 const compares=[near,ranked[1],ranked[2],far];
 const bio=p=>{const story=stories[p.name];const i=questions.findIndex(q=>q.d===story.axis);return `<div class="fact"><b>你在相关情境中的选择</b><p>${questions[i].q}</p><p>“${questions[i].a[answers[i]]}”</p><b>人物生平</b><p>${story.text}</p><small>这段经历与题目围绕相近的话题；人物画像是趣味设定，不能由单个事迹直接推断性格。</small></div>`};
 lastResult={near,far};
 show('result',`<div class="page page-wide result"><button class="back" data-home>← 返回测试合集</button><div class="quiz-head"><div class="eyebrow">YOUR RESULT · ${questions.length} QUESTIONS</div><h1>跨越时空，遇见另一种自己。</h1><p>根据你的 ${questions.length} 个回答，在 ${people.length} 位人物的趣味画像中进行比较。</p></div>
 <article class="match" data-reveal>${portrait(near,'avatar-xl')}<div class="match-body"><span class="kicker">✳ 画像与你最相近</span><div class="match-title"><h2>${near.name}</h2><span class="score"><b data-count="${near.score}">${near.score}</b>% 相近</span></div><strong class="role">${near.title}</strong><p>你的回答与这份人物画像在「${similarities}」方面比较接近。</p>${bio(near)}</div></article>
 <section class="panel profile" data-reveal style="--d:.12s"><div class="profile-head"><div><h3>你的倾向画像</h3><p class="panel-intro">越靠外越偏向轴上的特质，越靠内越偏向括号里的另一端，没有好坏之分。</p></div><div class="compare" role="group" aria-label="选择雷达图的对比人物"><span>对比</span>${compares.map((p,i)=>`<button class="chip${i?'':' active'}" data-compare="${i}" aria-pressed="${!i}">${p.name}${p===far?' · 差异最大':''}</button>`).join('')}</div></div><div class="profile-body"><div class="radar-wrap" id="radar">${radar(user,near)}</div><div class="dimensions">${dimensions.map((d,i)=>`<div class="dimension"><div class="dimension-row"><span>${d[0]}</span><span>${d[1]}</span></div><div class="scale"><span style="left:${(5-user[i])/4*100}%"></span></div><div class="dimension-caption">${lean(i,user[i])}</div></div>`).join('')}</div></div></section>
 <div class="result-grid" data-reveal style="--d:.2s"><section class="panel"><h3>还有这些相近的画像</h3><p class="panel-intro">按本次测试中的画像距离排序。</p>${ranked.slice(1,3).map((p,i)=>`<div class="rank-row"><span class="rank-no">0${i+2}</span>${portrait(p,'avatar-md')}<div class="rank-info"><b>${p.name}</b><small>${p.title}</small><p class="rank-bio">${stories[p.name].text}</p><i class="mini-bar"><span style="width:${p.score}%"></span></i></div><span class="rank-score"><b data-count="${p.score}">${p.score}</b>%</span></div>`).join('')}</section>
 <section class="panel contrast">${portrait(far,'avatar-md')}<div><span class="kicker">✳ 画像与你差异较大</span><h4>${far.name}<span>${far.title}</span></h4><p>你的回答与这份人物画像在「${contrasts}」方面差异较大。</p>${bio(far)}</div></section></div>
 <p class="disclaimer" data-reveal>人物插画为原创艺术演绎。此为趣味探索：人物生平与编辑设定的人物画像是两回事。历史人物没有参与答题，画像不是对真实性格的测量；匹配只在本测试的 ${people.length} 位人物中比较，分数相同时按人物库顺序展示。本测试未经科学验证，不构成心理评估或历史定论。</p>
 <div class="result-actions" data-reveal><button class="primary" id="share">分享测试 <span>↗</span></button><button class="secondary" id="again">重新选择题量</button><button class="secondary" data-home>返回合集</button></div><p class="notice" aria-live="polite" id="notice"></p></div>`);
 app.querySelector('#again').onclick=chooseLength;
 app.querySelectorAll('[data-compare]').forEach(b=>b.onclick=()=>{app.querySelectorAll('[data-compare]').forEach(c=>{c.classList.toggle('active',c===b);c.setAttribute('aria-pressed',c===b)});app.querySelector('#radar').innerHTML=radar(user,compares[b.dataset.compare]);bindRadar()});bindRadar();
 app.querySelector('#share').onclick=async()=>{const data={title:'星笺 · 历史人物匹配测试',text:`我在星笺的趣味测试中匹配到了${near.name}，来看看你与哪位历史人物的画像更相近？`,url:location.href.split('#')[0]};try{if(navigator.share)await navigator.share(data);else{await navigator.clipboard.writeText(data.text+' '+data.url);document.querySelector('#notice').textContent='分享内容和测试链接已复制。'}}catch(e){document.querySelector('#notice').textContent='可复制浏览器地址分享给朋友。'}}
}
// 页头页脚的锚点链接：不在首页时先回到首页，再滚动到对应区块。
document.addEventListener('click',e=>{const a=e.target.closest('a[href^="#"]');if(!a)return;e.preventDefault();if(view!=='home')home();const t=app.querySelector(a.getAttribute('href'));t?t.scrollIntoView():window.scrollTo(0,0)});
// 答题时支持键盘：1–4 或 A–D 选择，← → 切换题目。
document.addEventListener('keydown',e=>{if(view!=='quiz'||e.ctrlKey||e.metaKey||e.altKey)return;const k=e.key.toUpperCase();let i='1234'.indexOf(k);if(i<0)i='ABCD'.indexOf(k);if(k.length===1&&i>=0){e.preventDefault();pick(i)}else if(e.key==='ArrowLeft')prev();else if(e.key==='ArrowRight')next()});
// 滚动后给页头加一点阴影。
addEventListener('scroll',()=>document.querySelector('.header').classList.toggle('scrolled',scrollY>8),{passive:true});
home();
